-- write-audit-publish: writes go to a branch readers cannot see
ALTER TABLE curated.page_views_hourly CREATE BRANCH audit_88121;
SET spark.wap.branch = audit_88121;
INSERT OVERWRITE curated.page_views_hourly
SELECT date_trunc('hour', event_ts) AS hour, product_id, channel,
       count(*) AS views, count(DISTINCT session_id) AS sessions
FROM cleaned.events
WHERE event_type = 'page_view'
  AND hours(event_ts) IN ('2026-11-10T14', '2026-11-10T13', '2026-11-08T21')
GROUP BY 1, 2, 3;

